   if(!IsLoaded)return;
   var hwnd=new System.Windows.Interop.WindowInteropHelper(this).Handle;
   if(!fullscreen){
    RememberCurrentThickness();fullscreenWasDocked=Docked;fullscreenResize=ResizeMode;fullscreenState=WindowState;WindowGeometry.GetWindowRect(hwnd,out fullscreenRestore);
    if(fullscreenWasDocked)reservation.Unregister(false);
    fullscreen=true;WindowState=WindowState.Normal;ResizeMode=ResizeMode.NoResize;Topmost=true;
    var screen=WindowGeometry.Bounds(hwnd,false);
    WindowGeometry.SetWindowPos(hwnd,new IntPtr(-1),screen.left,screen.top,screen.right-screen.left,screen.bottom-screen.top,0x40);
   }else{
    fullscreen=false;ResizeMode=fullscreenResize;
