    else WindowGeometry.SetWindowPos(hwnd,IntPtr.Zero,fullscreenRestore.left,fullscreenRestore.top,fullscreenRestore.right-fullscreenRestore.left,fullscreenRestore.bottom-fullscreenRestore.top,0x40);
