   }
   var chrome=System.Windows.Shell.WindowChrome.GetWindowChrome(this);if(chrome!=null)chrome.ResizeBorderThickness=new Thickness(fullscreen||ResizeMode==ResizeMode.NoResize?0:5);
   if(fullscreenButton!=null){string tip=fullscreen?"退出全屏 (F11 / Esc)":"全屏 (F11)";fullscreenButton.Content=Design.Icon(fullscreen?"restore":"fullscreen");fullscreenButton.ToolTip=tip;System.Windows.Automation.AutomationProperties.SetName(fullscreenButton,tip);}
   ResizePanels();RenderCards();
  }
