   Func<bool,Border> fade=top=>{var color=(Color)ColorConverter.ConvertFromString(Design.Surface);var clear=Color.FromArgb(0,color.R,color.G,color.B);return new Border{Height=18,IsHitTestVisible=false,VerticalAlignment=top?VerticalAlignment.Top:VerticalAlignment.Bottom,Background=new LinearGradientBrush(top?color:clear,top?clear:color,new Point(0,0),new Point(0,1)),Opacity=0};};
