   var row=new Grid{Height=12,Visibility=Visibility.Collapsed};Grid.SetRow(row,2);
   var track=new Grid{Width=56,Height=12,Background=Brushes.Transparent,Cursor=Cursors.Hand,ToolTip="滚动位置"};
   track.Children.Add(new Border{Height=3,Background=Design.B(Design.Line),VerticalAlignment=VerticalAlignment.Center,CornerRadius=new CornerRadius(1.5)});
   var thumb=new Border{Height=3,Background=Design.B(Design.Muted),Opacity=.65,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Center,CornerRadius=new CornerRadius(1.5)};track.Children.Add(thumb);row.Children.Add(track);grid.Children.Add(row);
