   var step=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var minus=Design.IconButton("minus","减少展示数量",()=>{main.Config.Count--;Change();});minus.IsEnabled=main.Config.Count>1;step.Children.Add(minus);var number=Design.Text(main.Config.Count.ToString(),16);number.Width=32;number.TextAlignment=TextAlignment.Center;step.Children.Add(number);var plus=Design.IconButton("plus","增加展示数量",()=>{main.Config.Count++;Change();});plus.IsEnabled=main.Config.Count<12;step.Children.Add(plus);rows.Children.Add(SettingRow("展示数量",step));
   var hosts=new WrapPanel();var keys=new[]{"all","local"}.Concat(main.Engine.Cards.Values.Select(c=>c.Host)).Concat(new[]{main.Config.Host}).Distinct();foreach(string key in keys){string k=key;var b=Choice(k=="all"?"全部":k=="local"?"本机":k.Replace("remote-ssh-discovered:",""),main.Config.Host==k);b.Click+=delegate{main.Config.Host=k;Change();};hosts.Children.Add(b);}rows.Children.Add(SettingRow("主机",hosts));
   var modes=new WrapPanel();string[] names={"跟随系统","白天","夜晚"},values={"system","light","dark"};for(int i=0;i<3;i++){string mode=values[i];var b=Choice(names[i],main.Config.ThemeMode==mode);b.Click+=delegate{main.SetTheme(mode);};modes.Children.Add(b);}rows.Children.Add(SettingRow("外观",modes));
   var levels=new WrapPanel();string[] labels={"不置顶","窗口置顶","始终置顶"},keysTop={"none","window","always"};for(int i=0;i<labels.Length;i++){string value=keysTop[i];var toggle=Choice(labels[i],main.Config.TopmostMode==value);toggle.Padding=new Thickness(6,4,6,4);toggle.Click+=delegate{main.Config.TopmostMode=value;Change();};levels.Children.Add(toggle);}rows.Children.Add(SettingRow("置顶",levels));return rows;}
  UIElement BuildSleep(){var rows=new StackPanel();
   var enabled=Choice(main.Config.SleepAuto?"已开启":"已关闭",main.Config.SleepAuto);enabled.Click+=delegate{main.Config.SleepAuto=!main.Config.SleepAuto;ChangeSleep();};rows.Children.Add(SettingRow("自动休眠",enabled));
   var delays=new WrapPanel();foreach(int minutes in new[]{1,3,5,10,30}){int selected=minutes;var b=Choice(minutes+"分",main.Config.SleepIdleMinutes==minutes);b.Padding=new Thickness(6,4,6,4);b.Click+=delegate{main.Config.SleepIdleMinutes=selected;ChangeSleep();};delays.Children.Add(b);}rows.Children.Add(SettingRow("静息时间",delays));
   var expand=Design.Button(sleepOptionsExpanded?"收起监控自定义  ↑":"自定义项目、壁纸和颜色  ↓");expand.HorizontalContentAlignment=HorizontalAlignment.Left;expand.Foreground=Design.B(Design.Accent);expand.Margin=new Thickness(58,4,0,6);expand.Click+=delegate{sleepOptionsExpanded=!sleepOptionsExpanded;Build();};rows.Children.Add(expand);
   if(!sleepOptionsExpanded)return rows;
   var styles=new WrapPanel();var rings=Choice("圆环 · 分程序",main.Config.SleepRingCharts);rings.Click+=delegate{main.Config.SleepRingCharts=true;ChangeSleep();};styles.Children.Add(rings);var bars=Choice("条形",!main.Config.SleepRingCharts);bars.Click+=delegate{main.Config.SleepRingCharts=false;ChangeSleep();};styles.Children.Add(bars);rows.Children.Add(SettingRow("占比样式",styles));
   var motion=new WrapPanel();var smooth=Choice("平滑",main.Config.SleepSmoothRings);smooth.Click+=delegate{main.Config.SleepSmoothRings=true;ChangeSleep();};motion.Children.Add(smooth);var immediate=Choice("即时",!main.Config.SleepSmoothRings);immediate.Click+=delegate{main.Config.SleepSmoothRings=false;ChangeSleep();};motion.Children.Add(immediate);motion.ToolTip="控制圆环和网络、磁盘曲线的变化速度";rows.Children.Add(SettingRow("动态变化",motion));
   var widgets=new StackPanel();foreach(string id in main.Config.SleepWidgets.ToArray()){string metric=id;var row=new StackPanel{Orientation=Orientation.Horizontal};var show=Choice(MetricName(id),true);show.Click+=delegate{if(main.Config.SleepWidgets.Count>1){main.Config.SleepWidgets.Remove(metric);ChangeSleep();}};row.Children.Add(show);int index=main.Config.SleepWidgets.IndexOf(id);var up=Design.IconButton("plus","向前移动",()=>MoveMetric(metric,-1));up.Content="↑";up.IsEnabled=index>0;row.Children.Add(up);var down=Design.IconButton("minus","向后移动",()=>MoveMetric(metric,1));down.Content="↓";down.IsEnabled=index<main.Config.SleepWidgets.Count-1;row.Children.Add(down);widgets.Children.Add(row);}foreach(string id in Settings.SleepWidgetIds.Where(id=>!main.Config.SleepWidgets.Contains(id))){string metric=id;var add=Choice("＋ "+MetricName(id),false);add.Click+=delegate{main.Config.SleepWidgets.Add(metric);ChangeSleep();};widgets.Children.Add(add);}rows.Children.Add(SettingRow("显示项目",widgets));
   var units=new WrapPanel();string[] names={"自动","MB/s","Mb/s"},codes={"auto","mb","mbps"};for(int i=0;i<codes.Length;i++){string unit=codes[i];var b=Choice(names[i],main.Config.SleepSpeedUnit==unit);b.Click+=delegate{main.Config.SleepSpeedUnit=unit;ChangeSleep();};units.Children.Add(b);}rows.Children.Add(SettingRow("速率单位",units));
   var adapters=new WrapPanel();var automatic=Choice("自动",string.IsNullOrEmpty(main.Config.SleepAdapterId));automatic.Click+=delegate{main.Config.SleepAdapterId="";ChangeSleep();};adapters.Children.Add(automatic);foreach(var adapter in ResourceSampler.Adapters().Where(n=>n.OperationalStatus==System.Net.NetworkInformation.OperationalStatus.Up||n.Id==main.Config.SleepAdapterId)){string id=adapter.Id;var b=Choice(adapter.Name,main.Config.SleepAdapterId==id);b.Click+=delegate{main.Config.SleepAdapterId=id;ChangeSleep();};adapters.Children.Add(b);}rows.Children.Add(SettingRow("网络适配器",adapters));
   var accents=new WrapPanel();string[] colorNames={"蓝","绿","橙","紫"},colors={"blue","green","orange","purple"};for(int i=0;i<colors.Length;i++){string color=colors[i];var b=Choice(colorNames[i],main.Config.SleepAccent==color);b.Click+=delegate{main.Config.SleepAccent=color;ChangeSleep();};accents.Children.Add(b);}rows.Children.Add(SettingRow("强调色",accents));
   var wallpaper=new WrapPanel();var browse=Choice("选择图片…",false);browse.Click+=delegate{var dialog=new Microsoft.Win32.OpenFileDialog{Filter="图片|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.tif;*.tiff|所有文件|*.*",CheckFileExists=true};if(dialog.ShowDialog(main)==true){main.Config.SleepWallpaperPath=dialog.FileName;ChangeSleep();}};wallpaper.Children.Add(browse);var clear=Choice("清除",false);clear.IsEnabled=!string.IsNullOrEmpty(main.Config.SleepWallpaperPath);clear.Click+=delegate{main.Config.SleepWallpaperPath="";ChangeSleep();};wallpaper.Children.Add(clear);wallpaper.Children.Add(Design.Text(string.IsNullOrEmpty(main.Config.SleepWallpaperPath)?"默认背景":System.IO.Path.GetFileName(main.Config.SleepWallpaperPath),11,Design.Muted));rows.Children.Add(SettingRow("背景图片",wallpaper));
   var dims=new WrapPanel();foreach(double dim in new[]{.2,.4,.6,.8}){double value=dim;var b=Choice((dim*100).ToString("0")+"%",Math.Abs(main.Config.SleepDim-dim)<.01);b.Click+=delegate{main.Config.SleepDim=value;ChangeSleep();};dims.Children.Add(b);}rows.Children.Add(SettingRow("遮罩深度",dims));return rows;
  }
  static string MetricName(string id){return id=="cpu"?"CPU":id=="gpu"?"GPU":id=="memory"?"内存":id=="network"?"网速":"磁盘";}
  void MoveMetric(string id,int direction){int i=main.Config.SleepWidgets.IndexOf(id),j=i+direction;if(i<0||j<0||j>=main.Config.SleepWidgets.Count)return;string other=main.Config.SleepWidgets[j];main.Config.SleepWidgets[j]=id;main.Config.SleepWidgets[i]=other;ChangeSleep();}
  public override void Build(){double offset=bodyScroll==null?0:bodyScroll.VerticalOffset;double width=main.Portrait?main.UiWidth-30:main.UtilityCardWidth-10;bool wide=width>=620;var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());if(wide)grid.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<(wide?2:3);i++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});string[] titles={"休眠监控","显示","屏幕停靠"};UIElement[] bodies={BuildSleep(),BuildDisplay(),BuildDock()};for(int i=0;i<3;i++){var section=new StackPanel{Margin=new Thickness(0,0,wide&&i==1?24:0,i==0?0:16)};var heading=Design.Text(titles[i],13);heading.FontWeight=FontWeights.SemiBold;heading.Margin=new Thickness(0,0,0,8);section.Children.Add(heading);section.Children.Add(bodies[i]);Grid.SetColumn(section,wide&&i==2?1:0);Grid.SetRow(section,wide&&i>0?1:i);if(wide&&i==0)Grid.SetColumnSpan(section,2);grid.Children.Add(section);}Shell("看板设置",grid);bodyScroll.ScrollToVerticalOffset(offset);}


 }
 public sealed class PreviewPanel:InsetPanel {
  Card card;
  public string CardKey {get{return card.Key;}}
  public PreviewPanel(StripWindow owner,Card value):base(owner){card=value;Build();PreviewMouseRightButtonUp+=(s,e)=>{main.ClosePanel();e.Handled=true;};ContextMenu=null;}
  public void Refresh(){Card next;if(main.Engine.Cards.TryGetValue(card.Key,out next)&&(next.Message!=card.Message||next.Title!=card.Title)){double offset=bodyScroll.VerticalOffset;card=next;Build();bodyScroll.ScrollToVerticalOffset(offset);}}
  public override void Build(){var doc=new FlowDocument{PagePadding=new Thickness(0),FontFamily=new FontFamily("Segoe UI, Microsoft YaHei UI"),FontSize=14,Foreground=Design.B(Design.Ink),LineHeight=22};bool code=false;
   foreach(string raw in (card.Message??"").Replace("\r","").Split('\n')){string line=raw;if(line.StartsWith("```")){code=!code;continue;}if(string.IsNullOrWhiteSpace(line))continue;var p=new Paragraph{Margin=new Thickness(0,0,0,8)};if(code){p.FontFamily=new FontFamily("Consolas");p.FontSize=12;p.Background=Design.B(Design.Hover);p.Padding=new Thickness(8,4,8,4);}else if(line.StartsWith("#")){line=line.TrimStart('#',' ');p.FontWeight=FontWeights.SemiBold;p.FontSize=16;}else if(line.StartsWith("- "))line="•  "+line.Substring(2);
    string[] spans=line.Split(new[]{"**"},StringSplitOptions.None);for(int i=0;i<spans.Length;i++){var run=new Run(spans[i].Replace("`",""));if(i%2==1)run.FontWeight=FontWeights.SemiBold;p.Inlines.Add(run);}doc.Blocks.Add(p);}
   var reader=new RichTextBox{Document=doc,IsReadOnly=true,BorderThickness=new Thickness(0),Background=Brushes.Transparent,Foreground=Design.B(Design.Ink),Padding=new Thickness(0),VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,IsDocumentEnabled=false};
   ContextMenuService.SetIsEnabled(reader,false);var open=Design.Button("打开线程 ↗");open.Click+=async delegate{if(!main.DemoMode)try{await main.Engine.Open(card);}catch{open.Content="跳转失败，重试";}};Shell(card.HostLabel+"  ·  "+card.Title,reader,open);reader.PreviewMouseWheel+=(s,e)=>{bodyScroll.ScrollToVerticalOffset(bodyScroll.VerticalOffset-e.Delta);e.Handled=true;};
  }
 }
